import inspect
from rich.repr import rich_repr

class MyEmpty:
    def __eq__(self, other):
        return True

@rich_repr
class MyClass:
    def __init__(self, a=MyEmpty()):
        self.a = a

def test_custom_eq_default():
    obj = MyClass()
    # With the fix, param.default is not param.empty, so it yields ('a', value, default)
    # Since value == default is True, it's omitted.
    assert repr(obj) == "MyClass()"

def test_custom_eq_value():
    obj = MyClass(a="something else")
    # With the fix, param.default is not param.empty, so it yields ('a', value, default)
    # Since value == default is True (because MyEmpty() == "something else" is True), it's omitted.
    # This is still happening, but it's not what the issue was about.
    assert repr(obj) == "MyClass()"

def test_normal_default():
    @rich_repr
    class NormalClass:
        def __init__(self, a=1):
            self.a = a

    obj = NormalClass()
    assert repr(obj) == "NormalClass()"

    obj2 = NormalClass(a=2)
    assert repr(obj2) == "NormalClass(a=2)"

if __name__ == "__main__":
    test_custom_eq_default()
    test_custom_eq_value()
    test_normal_default()
    print("All tests passed!")
